-- 8. Update meetings RLS to support org-based access
-- (Replaces the meetings policies from 002_hardening.sql with org-aware versions)
DO $$
BEGIN
  EXECUTE 'DROP POLICY IF EXISTS meetings_select_for_participants ON public.meetings';
  EXECUTE 'DROP POLICY IF EXISTS meetings_insert_owner_only ON public.meetings';
  EXECUTE 'DROP POLICY IF EXISTS meetings_modify_owner_only ON public.meetings';

  EXECUTE $pol$
    CREATE POLICY meetings_select_for_org_or_participant
      ON public.meetings
      FOR SELECT
      USING (
        owner = (select auth.uid())
        OR (
          org_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.org_members om
            WHERE om.org_id = public.meetings.org_id
              AND om.user_id = (select auth.uid())
          )
        )
        OR EXISTS (
          SELECT 1 FROM public.meeting_participants mp
          WHERE mp.meeting_id = public.meetings.id
            AND mp.user_id = (select auth.uid())
        )
      );

    CREATE POLICY meetings_insert_owner_or_org_member
      ON public.meetings
      FOR INSERT
      WITH CHECK (
        owner = (select auth.uid())
        OR (
          org_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.org_members om
            WHERE om.org_id = public.meetings.org_id
              AND om.user_id = (select auth.uid())
          )
        )
      );

    CREATE POLICY meetings_modify_owner_or_org_admin_update
      ON public.meetings
      FOR UPDATE
      USING (
        owner = (select auth.uid())
        OR (
          org_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.org_members om
            WHERE om.org_id = public.meetings.org_id
              AND om.user_id = (select auth.uid())
              AND om.role = 'admin'
          )
        )
      )
      WITH CHECK (
        owner = (select auth.uid())
        OR (
          org_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.org_members om
            WHERE om.org_id = public.meetings.org_id
              AND om.user_id = (select auth.uid())
              AND om.role = 'admin'
          )
        )
      );

    CREATE POLICY meetings_modify_owner_or_org_admin_delete
      ON public.meetings
      FOR DELETE
      USING (
        owner = (select auth.uid())
        OR (
          org_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.org_members om
            WHERE om.org_id = public.meetings.org_id
              AND om.user_id = (select auth.uid())
              AND om.role = 'admin'
          )
        )
      )
        owner = (select auth.uid())
        OR (
          org_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.org_members om
            WHERE om.org_id = public.meetings.org_id
              AND om.user_id = (select auth.uid())
              AND om.role = 'admin'
          )
        )
      );
  $pol$;
END$$

-- RLS POLICIES: Enrollments
create policy "Owners can manage enrollments"
  on classroom_enrollments for all
  using (
    exists (
      select 1 from classrooms 
      where id = classroom_enrollments.classroom_id 
      and owner_id = auth.uid()
    )
  )

create policy "Students can view their own enrollments"
  on classroom_enrollments for select
  using (student_id = auth.uid())

create policy "Enrolled students can view lessons"
  on classroom_lessons for select
  using (
    exists (
      select 1 from classroom_enrollments
      where classroom_id = classroom_lessons.classroom_id
      and student_id = auth.uid()
      and enrollment_status = 'active'
    )
  )

-- Break recursive RLS policy chains across organization, meeting, and classroom access.
-- No application data is modified.

create or replace function public.is_org_member(target_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
set row_security = off
as $$
  select exists (
    select 1
    from public.org_members om
    where om.org_id = target_org_id
      and om.user_id = auth.uid()
  );
$$;

create or replace function public.is_org_admin(target_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
set row_security = off
as $$
  select exists (
    select 1
    from public.org_members om
    where om.org_id = target_org_id
      and om.user_id = auth.uid()
      and om.role = 'admin'
  );
$$;

