DO $duplicate_precheck$
DECLARE
  duplicate_group_count bigint;
  duplicate_row_count bigint;
BEGIN
  SELECT count(*), coalesce(sum(duplicate_count - 1), 0)
  INTO duplicate_group_count, duplicate_row_count
  FROM (
    SELECT count(*) AS duplicate_count
    FROM public.meeting_participants
    GROUP BY meeting_id, user_id
    HAVING count(*) > 1
  ) duplicate_groups;

  IF duplicate_group_count > 0 THEN
    RAISE EXCEPTION USING
      ERRCODE = '23505',
      MESSAGE = format(
        'Cannot add participant uniqueness: found %s duplicate group(s) and %s excess row(s).',
        duplicate_group_count,
        duplicate_row_count
      );
  END IF;
END
$duplicate_precheck$;

